import os

# Chemin vers le fichier sécurisé
file_path = "secure_directory/secure_file.txt"

# Vérification que le fichier existe
if not os.path.exists(file_path):
    print("Erreur : Le fichier n'existe pas.")
else:
    try:
        # Lecture du fichier ligne par ligne
        with open(file_path, 'r', encoding='utf-8') as file:
            lines = file.readlines()

        # Affichage du contenu ligne par ligne
        print("Contenu du fichier :")
        for line in lines:
            print(line.strip())

        # Demande à l'utilisateur de saisir une chaîne de recherche
        search_string = input("\nEntrez la chaîne à rechercher : ")

        # Recherche de la chaîne dans le fichier
        found_lines = []
        for line in lines:
            if search_string in line:
                found_lines.append(line.strip())

        # Affichage des lignes trouvées
        if found_lines:
            print(f"\nLignes contenant '{search_string}' :")
            for line in found_lines:
                print(line)
        else:
            print(f"\nAucune ligne ne contient '{search_string}'.")

    except PermissionError:
        print("Erreur : Permission refusée pour accéder au fichier.")
    except FileNotFoundError:
        print("Erreur : Fichier introuvable.")
    except Exception as e:
        print(f"Une erreur inattendue s'est produite : {e}")

