import json
import os
import yaml

def load_config(file_path, default_config={"theme": "light", "language": "en"}):
    safe_directory = "/safe/config/directory"
    full_path = os.path.join(safe_directory, file_path)

    if not os.path.exists(full_path):
        return default_config

    if not full_path.endswith(('.json', '.yaml', '.yml')):
        return default_config

    try:
        if full_path.endswith('.json'):
            with open(full_path, 'r', encoding='utf-8') as file:
                return json.load(file)
        elif full_path.endswith(('.yaml', '.yml')):
            with open(full_path, 'r', encoding='utf-8') as file:
                return yaml.safe_load(file)
    except (json.JSONDecodeError, yaml.YAMLError, IOError):
        return default_config

